class MockResponse {
    statusCode;
    headers;
    responseBody;
    responseJson;
    constructor(statusCode, headers, responseBody, responseJson) {
        this.statusCode = statusCode;
        this.headers = headers;
        this.responseBody = responseBody;
        this.responseJson = responseJson;
    }
    async text() {
        return this.responseBody;
    }
    async json() {
        return (this.responseJson ?? JSON.parse(this.responseBody));
    }
}
export class MockHttpClient {
    calls = [];
    cookies = new Map();
    stubs = [];
    onGet(matcher, ...responses) {
        this.stubs.push({ matcher, method: "GET", responses });
    }
    onPost(matcher, ...responses) {
        this.stubs.push({ matcher, method: "POST", responses });
    }
    setCookie(name, value) {
        this.cookies.set(name, value);
    }
    async get(url) {
        return this.respond("GET", url);
    }
    async postJson(url, body) {
        return this.respond("POST", url, body);
    }
    async respond(method, url, body) {
        const headers = {};
        if (this.cookies.size > 0) {
            headers.cookie = [...this.cookies.entries()].map(([name, value]) => `${name}=${value}`).join("; ");
        }
        this.calls.push({ body, headers, method, url });
        const stub = this.stubs.find((candidate) => candidate.method === method && candidate.responses.length > 0 && matches(candidate.matcher, url));
        if (!stub || stub.responses.length === 0) {
            throw new Error(`Unexpected ${method} request to ${url}`);
        }
        const response = stub.responses.shift();
        return new MockResponse(response.statusCode ?? 200, response.headers ?? {}, response.body ?? JSON.stringify(response.json ?? {}), response.json);
    }
}
function matches(matcher, url) {
    if (typeof matcher === "string") {
        return matcher === url;
    }
    if (matcher instanceof RegExp) {
        return matcher.test(url);
    }
    return matcher(url);
}
